/**
 * log-mel used by DhWenet.calcmfcc / mfcc.log_mel.
 * n_fft=1024, hop=160, win=800, n_mels=80, preemphasis=0.97, ref_db=20.
 */

const N_FFT = 1024;
const HOP = 160;
const WIN = 800;
const N_MELS = 80;
const PREEMPH = 0.97;
const REF_DB = 20;
const SR = 16000;

function hzToMel(f) {
  const fMin = 0;
  const fSp = 200 / 3;
  const minLogHz = 1000;
  const minLogMel = (minLogHz - fMin) / fSp;
  const logstep = Math.log(6.4) / 27;
  if (f >= minLogHz) return minLogMel + Math.log(f / minLogHz) / logstep;
  return (f - fMin) / fSp;
}

function melToHz(mels) {
  const fSp = 200 / 3;
  const minLogHz = 1000;
  const minLogMel = minLogHz / fSp;
  const logstep = Math.log(6.4) / 27;
  const out = new Float64Array(mels.length);
  for (let i = 0; i < mels.length; i++) {
    const m = mels[i];
    out[i] = m >= minLogMel ? Math.exp((m - minLogMel) * logstep) * minLogHz : m * fSp;
  }
  return out;
}

function linspace(a, b, n) {
  const out = new Float64Array(n);
  if (n === 1) {
    out[0] = a;
    return out;
  }
  const step = (b - a) / (n - 1);
  for (let i = 0; i < n; i++) out[i] = a + step * i;
  return out;
}

let melBasis = null;
function getMelBasis() {
  if (melBasis) return melBasis;
  const nFft2 = 1 + (N_FFT >> 1);
  const fMax = SR / 2;
  const fftfreqs = linspace(0, fMax, nFft2);
  const minMel = hzToMel(0);
  const maxMel = hzToMel(fMax);
  const mels = linspace(minMel, maxMel, N_MELS + 2);
  const melF = melToHz(mels);
  const weights = Array.from({ length: N_MELS }, () => new Float64Array(nFft2));
  for (let i = 0; i < N_MELS; i++) {
    const fdiffL = melF[i + 1] - melF[i];
    const fdiffU = melF[i + 2] - melF[i + 1];
    for (let j = 0; j < nFft2; j++) {
      const lower = -(melF[i] - fftfreqs[j]) / fdiffL;
      const upper = (melF[i + 2] - fftfreqs[j]) / fdiffU;
      weights[i][j] = Math.max(0, Math.min(lower, upper));
    }
    const enorm = 2 / (melF[i + 2] - melF[i]);
    for (let j = 0; j < nFft2; j++) weights[i][j] *= enorm;
  }
  melBasis = weights;
  return weights;
}

let hann = null;
function getHann() {
  if (hann) return hann;
  hann = new Float32Array(N_FFT);
  const insert = (N_FFT - WIN) >> 1;
  for (let k = 1; k <= WIN; k++) {
    hann[k - 1 + insert] = 0.5 * (1 - Math.cos((2 * Math.PI * k) / (WIN + 1)));
  }
  return hann;
}

function fft1024(re, im) {
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      const tr = re[i];
      re[i] = re[j];
      re[j] = tr;
      const ti = im[i];
      im[i] = im[j];
      im[j] = ti;
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    const wlenRe = Math.cos(ang);
    const wlenIm = Math.sin(ang);
    for (let i = 0; i < n; i += len) {
      let wRe = 1;
      let wIm = 0;
      const half = len >> 1;
      for (let j = 0; j < half; j++) {
        const uRe = re[i + j];
        const uIm = im[i + j];
        const vRe = re[i + j + half] * wRe - im[i + j + half] * wIm;
        const vIm = re[i + j + half] * wIm + im[i + j + half] * wRe;
        re[i + j] = uRe + vRe;
        im[i + j] = uIm + vIm;
        re[i + j + half] = uRe - vRe;
        im[i + j + half] = uIm - vIm;
        const nwRe = wRe * wlenRe - wIm * wlenIm;
        wIm = wRe * wlenIm + wIm * wlenRe;
        wRe = nwRe;
      }
    }
  }
}

function reflectPad(x, pad) {
  const n = x.length;
  const out = new Float32Array(n + pad * 2);
  for (let i = 0; i < pad; i++) {
    const src = pad - i;
    out[i] = x[Math.min(n - 1, src)];
  }
  out.set(x, pad);
  for (let i = 0; i < pad; i++) {
    out[pad + n + i] = x[Math.max(0, n - 2 - i)];
  }
  return out;
}

/**
 * @param {Float32Array} samples normalized PCM
 * @returns {Float32Array} melcnt * 80, frame-major
 */
export function logMel(samples) {
  const emphasis = new Float32Array(samples.length);
  for (let i = 1; i < samples.length; i++) {
    emphasis[i] = samples[i] - PREEMPH * samples[i - 1];
  }
  const padded = reflectPad(emphasis, N_FFT >> 1);
  const window = getHann();
  const nFrames = Math.floor((padded.length - N_FFT) / HOP) + 1;
  const nCoef = (N_FFT >> 1) + 1;
  const power = Array.from({ length: nFrames }, () => new Float64Array(nCoef));
  const re = new Float32Array(N_FFT);
  const im = new Float32Array(N_FFT);
  for (let f = 0; f < nFrames; f++) {
    const off = f * HOP;
    for (let i = 0; i < N_FFT; i++) {
      re[i] = padded[off + i] * window[i];
      im[i] = 0;
    }
    fft1024(re, im);
    const row = power[f];
    for (let k = 0; k < nCoef; k++) {
      const mag = Math.hypot(re[k], im[k]);
      row[k] = mag * mag;
    }
  }
  const basis = getMelBasis();
  const mel = new Float32Array(nFrames * N_MELS);
  const ln10 = 2.302585092994046;
  for (let f = 0; f < nFrames; f++) {
    for (let m = 0; m < N_MELS; m++) {
      let s = 0;
      const w = basis[m];
      const p = power[f];
      for (let k = 0; k < nCoef; k++) s += w[k] * p[k];
      mel[f * N_MELS + m] = (Math.log(s + 1e-5) / ln10) * 10 - REF_DB;
    }
  }
  return mel;
}
